p=Path(f'items/{ids[2]}.md');raw=p.read_text()
raw=raw.replace('J. Binney and D. Skinner, The Physics of Quantum Mechanics, Section 3.2 pp. 38-41 (Galilean boosts, the boost phase and transforming between frames)','C. Torre, Galilean Relativity and the Path Integral Formalism in Quantum Mechanics, arXiv:2306.13487 (2023), Section 4 equations (4.23)-(4.24), pages 12-13: the boost phase and the transformed initial wave function; Section 6 equation (6.2), page 17: boost action on wave functions')
